def comp_ids(g, marker):
 R,C=len(g),len(g[0]); ids=[[-1]*C for _ in range(R)]; comps=[]
 for r in range(R):
  for c in range(C):
   if g[r][c]!=marker or ids[r][c]>=0: continue
   k=len(comps); cells=[]; q=[(r,c)]; ids[r][c]=k
   while q:
    rr,cc=q.pop(); cells.append((rr,cc))
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     nr,nc=rr+dr,cc+dc
     if 0<=nr<R and 0<=nc<C and g[nr][nc]==marker and ids[nr][nc]<0:
      ids[nr][nc]=k;q.append((nr,nc))
   comps.append(cells)
 return ids,comps
