def aligned_edges(g, marker, ids, comps):
 R,C=len(g),len(g[0]); edges=[]
 for a,b in itertools.combinations(range(len(comps)),2):
  best=None
  # row aligned
  for r in range(R):
   ca=[c for rr,c in comps[a] if rr==r]; cb=[c for rr,c in comps[b] if rr==r]
   if ca and cb:
    for x in ca:
     for y in cb:
      if x==y: continue
      lo,hi=sorted((x,y)); path=[(r,c) for c in range(lo+1,hi)]
      if all(g[rr][cc]!=marker for rr,cc in path):
       t=(len(path),path)
       if best is None or t<best: best=t
  # col aligned
  for c in range(C):
   ra=[r for r,cc in comps[a] if cc==c]; rb=[r for r,cc in comps[b] if cc==c]
   if ra and rb:
    for x in ra:
     for y in rb:
      if x==y: continue
      lo,hi=sorted((x,y)); path=[(r,c) for r in range(lo+1,hi)]
      if all(g[rr][cc]!=marker for rr,cc in path):
       t=(len(path),path)
       if best is None or t<best: best=t
  if best: edges.append((best[0],a,b,best[1]))
 return sorted(edges,key=lambda e:(e[0], e[1],e[2],e[3]))
